  document.addEventListener('click',event=>{const sync=event.target.closest('[data-method-sync-branch]');if(sync){window.YV_BUILDER.setToolBranch(sync.dataset.methodSyncBranch,sync.dataset.branchId);window.YV_PLAN_CONTRACTS?.refreshTool(sync.dataset.methodSyncBranch);return;}if(event.target.closest('.method-detail a[href^="#"]'))app()?.closeDrawer();const button=event.target.closest('[data-method-jump]'),root=button?.closest('.method-detail');if(!root)return;const section=root.querySelector(`[data-method-section="${button.dataset.methodJump}"]`);if(!section)return;if(button.dataset.methodJump==='parameters')section.querySelector('.method-parameter-group')?.setAttribute('open','');markSection(root,button.dataset.methodJump);section.focus({preventScroll:true});const scroller=scrollContainer(root),behavior=app().prefs().reducedMotion||matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';if(scroller){scroller.scrollTo({top:Math.max(0,scroller.scrollTop+section.getBoundingClientRect().top-scroller.getBoundingClientRect().top-(scroller.clientTop||0)-navigationOffset(root)),behavior});}else section.scrollIntoView({block:'start',behavior});});
