  document.addEventListener('scroll',event=>{if(!['drawer','drawer-content'].includes(event.target.id)||scrollFrame)return;const scroller=event.target,root=scroller.querySelector('.method-detail');if(!root||scrollContainer(root)!==scroller)return;scrollFrame=requestAnimationFrame(()=>{scrollFrame=0;if(!root.isConnected||scrollContainer(root)!==scroller)return;const nav=root.querySelector('.method-jump-nav'),boundary=scroller.getBoundingClientRect().top+(scroller.clientTop||0)+navigationOffset(root);let active='inputs';root.querySelectorAll('[data-method-section]').forEach(section=>{if(section.getBoundingClientRect().top<=boundary+1&&nav.querySelector(`[data-method-jump="${section.dataset.methodSection}"]`))active=section.dataset.methodSection;});if(scroller.scrollTop>0&&scroller.scrollTop+scroller.clientHeight>=scroller.scrollHeight-4)active='sources';markSection(root,active);});},{capture:true,passive:true});
  document.addEventListener('change',event=>{if(!event.target.closest('.method-detail')||!event.target.matches('[data-inventory],[data-plan-param],[data-plan-tool]'))return;requestAnimationFrame(()=>{const root=document.querySelector('#drawer .method-detail');if(!root)return;const p=window.YV_BUILDER.getPlan(),tool=app().maps().tool.get(root.dataset.methodTool);if(!tool)return;const contextual=window.YV_INPUTS.toolContext(p,tool,app().data()),ids=(contextual.applicability?.requiredData||[]).filter(id=>app().data().categories.dataRequirements.some(r=>r.id===id));root.querySelector('[data-method-status="inputs"]').innerHTML=`${ids.filter(id=>p.availableData.includes(id)).length}<small> / ${ids.length}</small>`;root.querySelector('[data-method-status="parameters"]').innerHTML=`${contextual.parameters.filter(parameter=>String(contextual.resolvedParameters?.[parameter.name]??p.parameters[tool.id]?.[parameter.name]??'').trim()).length}<small> / ${contextual.parameters.length}</small>`;root.querySelector('[data-method-status="plan"]').textContent=t(p.tools.includes(tool.id)?'included':'notIncluded');});});
